questionvariables.text:
/* Design backwards: choose the quadratic form, then the answer is fixed.
   ftype in {1,2,3}: x^2, x^2+kk, kk*x^2. kk in [2,6] keeps forms 2/3 non-trivial. */
ftype : rand([1,2,3]);
kk    : rand_with_prohib(2,6,[]);

/* Build f as a Maxima function so f(a+h), f(a) are exact. */
if ftype = 1 then f(x) := x^2
elseif ftype = 2 then f(x) := x^2 + kk
else f(x) := kk*x^2;

fexpr : f(x);                 /* what the student sees for f(x) */
fa    : f(a);                 /* f(a) */
fah   : f(a+h);               /* f(a+h), unexpanded shown in worked solution */

/* Difference quotient pieces for the worked solution. */
numRaw       : fah - fa;                    /* unexpanded numerator */
numExpanded  : expand(fah) - expand(fa);   /* after expanding (a+h)^2 */
numCollected : expand(numRaw);             /* like terms collected */

/* Model answers. */
ta1 : expand(ratsimp(numRaw/h));   /* simplified AROC, h cancelled: 2a+h or 2kk*a+kk*h */
ta2 : expand(ev(ta1, h=0));        /* h->0 limit: 2a or 2kk*a */

/* KEY misconception: (a+h)^2 = a^2 + h^2, dropping the 2ah cross term.
   Numerator collapses to h^2 (or kk*h^2), so the cancelled answer is h (or kk*h). */
if ftype = 3 then wrong_cross : kk*h else wrong_cross : h;

/* Sign/limit slips for ans2 feedback: student keeps the +h and lets h->0 wrong,
   or reports the whole AROC as the limit. */
wrong_limit_keepsh : ta1;          /* forgot to let h->0, just restated AROC */

/* The (a+h)^2-bug limit, in case the student carries the bug through to ans2:
   limit of (h or kk*h) as h->0 is 0. */
wrong_cross_limit : 0;

feedbackvariables.text:
/* Does the student's answer still divide by h? denom() returns the denominator;
   if h is not free of it, they have left the raw quotient (or an equivalent that
   still divides by h). We branch on this FORM property, not just value.
   Inspect the student's LITERAL form - do NOT ratsimp first, or the h in the
   denominator would be cancelled away and the quotient wrongly accepted. */
hasq : is(not(freeof(h, denom(ans1))));
